1	#!/usr/bin/env node
2	/**
3	 * SessionStart Hook - Initializes session environment with project detection
4	 *
5	 * Fires: Once per session (startup, resume, clear, compact)
6	 * Purpose: Load config, detect project info, persist to env vars, output context
7	 *
8	 * Exit Codes:
9	 *   0 - Success (non-blocking, allows continuation)
10	 *
11	 * Core detection logic extracted to lib/project-detector.cjs for OpenCode plugin reuse.
12	 */
13	
14	// Crash wrapper
15	try {
16	  const fs = require('fs');
17	  const path = require('path');
18	  const os = require('os');
19	  const {
20	    loadConfig,
21	    readSessionState,
22	    writeEnv,
23	    updateSessionState,
24	    resolvePlanPath,
25	    getReportsPath,
26	    resolveNamingPattern,
27	    extractTaskListId,
28	    isHookEnabled
29	  } = require('./lib/ck-config-utils.cjs');
30	  const { createHookTimer, logHookCrash } = require('./lib/hook-logger.cjs');
31	  const { loadState, refreshStatuslineSnapshot } = require('./lib/session-state-manager.cjs');
32	  const { createEmptyActivitySnapshot } = require('./lib/statusline-session-cache.cjs');
33	
34	  // Early exit if hook disabled in config
35	  if (!isHookEnabled('session-init')) {
36	    process.exit(0);
37	  }
38	
39	  // Import shared project detection logic
40	  const {
41	    detectProjectType,
42	    detectPackageManager,
43	    detectFramework,
44	    getGitBranch,
45	    getGitRoot,
46	    getCodingLevelStyleName,
47	    getCodingLevelGuidelines,
48	    buildContextOutput
49	  } = require('./lib/project-detector.cjs');
50	
51	/**
52	 * One-time cleanup for orphaned .shadowed/ directories from skill-dedup hook (Issue #422)
53	 * The hook is disabled, but existing orphaned skills still need recovery on startup.
54	 */
55	function cleanupOrphanedShadowedSkills() {
56	  const shadowedDir = path.join(process.cwd(), '.claude', 'skills', '.shadowed');
57	  if (!fs.existsSync(shadowedDir)) return { restored: [], skipped: [], kept: [] };
58	
59	  const skillsDir = path.join(process.cwd(), '.claude', 'skills');
60	  const restored = [];
61	  const skipped = [];
62	  const kept = [];
63	
64	  try {
65	    const entries = fs.readdirSync(shadowedDir, { withFileTypes: true });
66	    for (const entry of entries) {
67	      if (!entry.isDirectory()) continue;
68	      const src = path.join(shadowedDir, entry.name);
69	      const dest = path.join(skillsDir, entry.name);
70	
71	      try {
72	        if (!fs.existsSync(dest)) {
73	          fs.renameSync(src, dest);
74	          restored.push(entry.name);
75	          continue;
76	        }
77	
78	        const orphanedSkill = path.join(src, 'SKILL.md');
79	        const localSkill = path.join(dest, 'SKILL.md');
80	        if (fs.existsSync(orphanedSkill) && fs.existsSync(localSkill)) {
81	          const orphanedContent = fs.readFileSync(orphanedSkill, 'utf8');
82	          const localContent = fs.readFileSync(localSkill, 'utf8');
83	          if (orphanedContent === localContent) {
84	            fs.rmSync(src, { recursive: true, force: true });
85	            skipped.push(entry.name);
86	          } else {
87	            kept.push(entry.name);
88	          }
89	        } else {
90	          fs.rmSync(src, { recursive: true, force: true });
91	          skipped.push(entry.name);
92	        }
93	      } catch (error) {
94	        process.stderr.write(`[session-init] Failed to process "${entry.name}": ${error.message}\n`);
95	      }
96	    }
97	
98	    const manifestFile = path.join(shadowedDir, '.dedup-manifest.json');
99	    if (fs.existsSync(manifestFile)) fs.unlinkSync(manifestFile);
100	    if (fs.existsSync(shadowedDir) && fs.readdirSync(shadowedDir).length === 0) {
101	      fs.rmdirSync(shadowedDir);
102	    }
103	
104	    return { restored, skipped, kept };
105	  } catch (error) {
106	    process.stderr.write(`[session-init] Shadowed cleanup error: ${error.message}\n`);
107	    return { restored, skipped, kept };
108	  }
109	}
110	
111	/**
112	 * Detect if this session is running inside an Agent Team.
113	 * Scans ~/.claude/teams/ for active team configs and checks membership.
114	 * Note: Returns first team found — Claude Code supports one team per session.
115	 * Note: Team lifecycle (creation/cleanup) is managed by Claude Code, not this hook.
116	 * @returns {{ teamName: string, memberCount: number } | null}
117	 */
118	function detectAgentTeam() {
119	  try {
120	    const teamsDir = path.join(os.homedir(), '.claude', 'teams');
121	    if (!fs.existsSync(teamsDir)) return null;
122	
123	    const teams = fs.readdirSync(teamsDir, { withFileTypes: true });
124	    for (const entry of teams) {
125	      if (!entry.isDirectory()) continue;
126	      const configPath = path.join(teamsDir, entry.name, 'config.json');
127	      if (!fs.existsSync(configPath)) continue;
128	      try {
129	        const config = JSON.parse(fs.readFileSync(configPath, 'utf8'));
130	        if (config.members && config.members.length > 0) {
131	          return { teamName: entry.name, memberCount: config.members.length };
132	        }
133	      } catch { /* skip malformed configs */ }
134	    }
135	    return null;
136	  } catch {
137	    return null;
138	  }
139	}
140	
141	function shouldWarmStatuslineCache(source, snapshot) {
142	  if (!['startup', 'resume', 'compact'].includes(source)) return false;
143	  return !snapshot || snapshot.warmed !== true;
144	}
145	
146	/**
147	 * Main hook execution
148	 */
149	async function main() {
150	  const timer = createHookTimer('session-init', { event: 'SessionStart' });
151	  try {
152	    const shadowedCleanup = cleanupOrphanedShadowedSkills();
153	    const stdin = fs.readFileSync(0, 'utf-8').trim();
154	    const data = stdin ? JSON.parse(stdin) : {};
155	    const envFile = process.env.CLAUDE_ENV_FILE;
156	    const source = data.source || 'unknown';
157	    const sessionId = data.session_id || null;
158	    const existingSession = sessionId ? readSessionState(sessionId) : null;
159	
160	    const config = loadConfig();
161	    const sessionStateEnabled = config.hooks?.['session-state'] !== false;
162	
163	    const detections = {
164	      type: detectProjectType(config.project?.type),
165	      pm: detectPackageManager(config.project?.packageManager),
166	      framework: detectFramework(config.project?.framework)
167	    };
168	
169	    // Resolve plan - now returns { path, resolvedBy }
170	    const resolved = resolvePlanPath(null, config);
171	
172	    if (sessionId) {
173	      updateSessionState(sessionId, prev => ({
174	        ...prev,
175	        sessionOrigin: process.cwd(),
176	        activePlan: resolved.resolvedBy === 'session' ? resolved.path : null,
177	        suggestedPlan: resolved.resolvedBy === 'branch' ? resolved.path : null,
178	        timestamp: Date.now(),
179	        source,
180	        statusline: prev.statusline || createEmptyActivitySnapshot()
181	      }));
182	    }
183	
184	    if (sessionStateEnabled && sessionId && shouldWarmStatuslineCache(source, existingSession?.statusline)) {
185	      await refreshStatuslineSnapshot(data);
186	    }
187	
188	    // Reports path only uses active plans, not suggested ones
189	    const reportsPath = getReportsPath(resolved.path, resolved.resolvedBy, config.plan, config.paths);
190	
191	    // Extract task list ID for Claude Code Tasks coordination (shared helper)
192	    const taskListId = extractTaskListId(resolved);
193	
194	    // Keep startup metadata cheap. Expensive enrichment is intentionally deferred.
195	    const staticEnv = {
196	      nodeVersion: process.version,
197	      osPlatform: process.platform,
198	      gitBranch: getGitBranch(),
199	      gitRoot: getGitRoot(),
200	      user: process.env.USERNAME || process.env.USER || process.env.LOGNAME || os.userInfo().username,
201	      locale: process.env.LANG || '',
202	      timezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
203	      claudeSettingsDir: path.resolve(__dirname, '..')
204	    };
205	
206	    // Compute base directory for absolute paths (Issue #327: use CWD for subdirectory support)
207	    // Git root is kept in staticEnv for reference, but CWD determines where files are created
208	    const baseDir = process.cwd();
209	
210	    // Compute resolved naming pattern (date + issue resolved, {slug} kept as placeholder)
211	    const namePattern = resolveNamingPattern(config.plan, staticEnv.gitBranch);
212	
213	    if (envFile) {
214	      // Session & plan config
215	      writeEnv(envFile, 'CK_SESSION_ID', sessionId || '');
216	      writeEnv(envFile, 'CK_PLAN_NAMING_FORMAT', config.plan.namingFormat);
217	      writeEnv(envFile, 'CK_PLAN_DATE_FORMAT', config.plan.dateFormat);
218	      writeEnv(envFile, 'CK_PLAN_ISSUE_PREFIX', config.plan.issuePrefix || '');
219	      writeEnv(envFile, 'CK_PLAN_REPORTS_DIR', config.plan.reportsDir);
220	
221	      // NEW: Resolved naming pattern for DRY file naming in agents
222	      // Example: "251212-1830-GH-88-{slug}" or "251212-1830-{slug}"
223	      // Agents use: `{agent-type}-$CK_NAME_PATTERN.md` and substitute {slug}
224	      writeEnv(envFile, 'CK_NAME_PATTERN', namePattern);
225	
226	      // Plan resolution
227	      writeEnv(envFile, 'CK_ACTIVE_PLAN', resolved.resolvedBy === 'session' ? resolved.path : '');
228	      writeEnv(envFile, 'CK_SUGGESTED_PLAN', resolved.resolvedBy === 'branch' ? resolved.path : '');
229	
230	      // Claude Code Tasks integration - enables multi-session/subagent coordination
231	      // Task list ID = plan directory name (shared across all sessions working on same plan)
232	      if (taskListId) {
233	        writeEnv(envFile, 'CLAUDE_CODE_TASK_LIST_ID', taskListId);
234	      }
235	
236	      // Paths - use absolute paths based on CWD for subdirectory workflow support (Issue #327)
237	      writeEnv(envFile, 'CK_GIT_ROOT', staticEnv.gitRoot || '');
238	      writeEnv(envFile, 'CK_REPORTS_PATH', path.join(baseDir, reportsPath));
239	      writeEnv(envFile, 'CK_DOCS_PATH', path.join(baseDir, config.paths.docs));
240	      writeEnv(envFile, 'CK_PLANS_PATH', path.join(baseDir, config.paths.plans));
241	      writeEnv(envFile, 'CK_PROJECT_ROOT', process.cwd());
242	
243	      // Project detection
244	      writeEnv(envFile, 'CK_PROJECT_TYPE', detections.type || '');
245	      writeEnv(envFile, 'CK_PACKAGE_MANAGER', detections.pm || '');
246	      writeEnv(envFile, 'CK_FRAMEWORK', detections.framework || '');
247	
248	      // NEW: Static environment info (so other hooks don't need to recompute)
249	      writeEnv(envFile, 'CK_NODE_VERSION', staticEnv.nodeVersion);
250	      writeEnv(envFile, 'CK_OS_PLATFORM', staticEnv.osPlatform);
251	      writeEnv(envFile, 'CK_GIT_BRANCH', staticEnv.gitBranch || '');
252	      writeEnv(envFile, 'CK_USER', staticEnv.user);
253	      writeEnv(envFile, 'CK_LOCALE', staticEnv.locale);
254	      writeEnv(envFile, 'CK_TIMEZONE', staticEnv.timezone);
255	      writeEnv(envFile, 'CK_CLAUDE_SETTINGS_DIR', staticEnv.claudeSettingsDir);
256	
257	      // Locale config
258	      if (config.locale?.thinkingLanguage) {
259	        writeEnv(envFile, 'CK_THINKING_LANGUAGE', config.locale.thinkingLanguage);
260	      }
261	      if (config.locale?.responseLanguage) {
262	        writeEnv(envFile, 'CK_RESPONSE_LANGUAGE', config.locale.responseLanguage);
263	      }
264	
265	      // Plan validation config (for /ck:plan validate, /ck:plan --hard, /ck:plan --parallel)
266	      const validation = config.plan?.validation || {};
267	      writeEnv(envFile, 'CK_VALIDATION_MODE', validation.mode || 'prompt');
268	      writeEnv(envFile, 'CK_VALIDATION_MIN_QUESTIONS', validation.minQuestions || 3);
269	      writeEnv(envFile, 'CK_VALIDATION_MAX_QUESTIONS', validation.maxQuestions || 8);
270	      writeEnv(envFile, 'CK_VALIDATION_FOCUS_AREAS', (validation.focusAreas || ['assumptions', 'risks', 'tradeoffs', 'architecture']).join(','));
271	
272	      // Coding level config (for output style selection)
273	      const codingLevel = config.codingLevel ?? 5;
274	      writeEnv(envFile, 'CK_CODING_LEVEL', codingLevel);
275	      writeEnv(envFile, 'CK_CODING_LEVEL_STYLE', getCodingLevelStyleName(codingLevel));
276	
277	    }
278	
279	    // Agent Teams detection — detect once, used for env vars and console output
280	    const teamInfo = detectAgentTeam();
281	    if (envFile && teamInfo) {
282	      writeEnv(envFile, 'CK_AGENT_TEAM', teamInfo.teamName);
283	      writeEnv(envFile, 'CK_AGENT_TEAM_MEMBERS', teamInfo.memberCount);
284	    }
285	
286	    console.log(`Session ${source}. ${buildContextOutput(config, detections, resolved, staticEnv.gitRoot)}`);
287	
288	    const hasCleanup =
289	      shadowedCleanup.restored.length > 0 ||
290	      shadowedCleanup.skipped.length > 0 ||
291	      shadowedCleanup.kept.length > 0;
292	    if (hasCleanup) {
293	      console.log(`\n[!] SKILL-DEDUP CLEANUP (Issue #422):`);
294	      console.log(`Recovered orphaned .shadowed/ directory from disabled skill-dedup hook.`);
295	      if (shadowedCleanup.restored.length > 0) {
296	        console.log(`Restored ${shadowedCleanup.restored.length} skill(s): ${shadowedCleanup.restored.join(', ')}`);
297	      }
298	      if (shadowedCleanup.skipped.length > 0) {
299	        console.log(`Removed ${shadowedCleanup.skipped.length} duplicate(s): ${shadowedCleanup.skipped.join(', ')}`);
300	      }
301	      if (shadowedCleanup.kept.length > 0) {
302	        console.log(`[!] Kept ${shadowedCleanup.kept.length} skill(s) for manual review (content differs): ${shadowedCleanup.kept.join(', ')}`);
303	        console.log(`    Review .claude/skills/.shadowed/ and merge changes manually.`);
304	      }
305	    }
306	
307	    if (sessionStateEnabled && (source === 'startup' || source === 'compact')) {
308	      const previousState = loadState(process.cwd());
309	      if (previousState) {
310	        if (source === 'compact') {
311	          console.log('\n--- Session State (Post-Compaction Recovery) ---');
312	          console.log(previousState);
313	          console.log('--- End Session State ---\n');
314	          console.log('Context was compacted. Above is your last saved progress. Resume from where you left off.');
315	          console.log('IMPORTANT: Re-read active plan files and todo list. Do NOT re-do completed work.');
316	        } else {
317	          console.log('\n--- Previous Session State ---');
318	          console.log(previousState);
319	          console.log('--- End Session State ---\n');
320	          console.log('Review above state from your last session. Continue where you left off or start fresh.');
321	        }
322	      }
323	    }
324	
325	    // Agent Teams: Show team context if running inside a team (uses cached result)
326	    if (teamInfo) {
327	      console.log(`[i] Agent Team detected: "${teamInfo.teamName}" (${teamInfo.memberCount} members)`);
328	      console.log(`    Team config: ~/.claude/teams/${teamInfo.teamName}/config.json`);
329	      console.log(`    Use /ck:team skill for orchestration templates.`);
330	    }
331	
332	    // Info: Show git root when running from subdirectory (Issue #327: now supported)
333	    if (staticEnv.gitRoot && staticEnv.gitRoot !== process.cwd()) {
334	      console.log(`📁 Subdirectory mode: Plans/docs will be created in current directory`);
335	      console.log(`   Git root: ${staticEnv.gitRoot}`);
336	    }
337	
338	    // MITIGATION: Issue #277 - Auto-compact can bypass AskUserQuestion approval gates
339	    // When context is compacted mid-workflow, the summarization may lose "pending approval" state.
340	    // This warning reminds Claude to verify if user approval was pending before proceeding.
341	    // Upstream bug: Claude Code CLI should preserve pending interactive state during compaction.
342	    if (source === 'compact') {
343	      console.log(`\n⚠️ CONTEXT COMPACTED - APPROVAL STATE CHECK:`);
344	      console.log(`If you were waiting for user approval via AskUserQuestion (e.g., Step 4 review gate),`);
345	      console.log(`you MUST re-confirm with the user before proceeding. Do NOT assume approval was given.`);
346	      console.log(`Use AskUserQuestion to verify: "Context was compacted. Please confirm approval to continue."`);
347	    }
348	
349	    // Auto-inject coding level guidelines (if not disabled)
350	    const codingLevel = config.codingLevel ?? -1;
351	    const guidelines = getCodingLevelGuidelines(codingLevel);
352	    if (guidelines) {
353	      console.log(`\n${guidelines}`);
354	    }
355	
356	    if (config.assertions?.length > 0) {
357	      console.log(`\nUser Assertions:`);
358	      config.assertions.forEach((assertion, i) => {
359	        console.log(`  ${i + 1}. ${assertion}`);
360	      });
361	    }
362	
363	    timer.end({ status: 'ok', exit: 0, note: source || 'session-start' });
364	    process.exit(0);
365	  } catch (error) {
366	    console.error(`SessionStart hook error: ${error.message}`);
367	    logHookCrash('session-init', error, { event: 'SessionStart' });
368	    process.exit(0);
369	  }
370	  }
371	
372	  main();
373	} catch (e) {
374	  try {
375	    const { logHookCrash } = require('./lib/hook-logger.cjs');
376	    logHookCrash('session-init', e, { event: 'SessionStart' });
377	  } catch (_) {}
378	  process.exit(0); // fail-open
379	}
