1	#!/usr/bin/env node
2	/**
3	 * knowledge-auto-refresh.cjs — SessionStart hook
4	 * Auto-refreshes stale persona knowledge in background (non-blocking)
5	 *
6	 * Triggers when:
7	 * - >30% of personas are stale (>30 days)
8	 * - On startup/resume/clear events
9	 *
10	 * Behavior:
11	 * - Queues top 5 most relevant stale personas for refresh
12	 * - Spawns background refresh (non-blocking)
13	 * - Updates knowledge-state.yaml after refresh
14	 *
15	 * Exit: Always 0 (non-blocking)
16	 */
17	
18	try {
19	  const fs = require('fs');
20	  const path = require('path');
21	  const { spawn } = require('child_process');
22	
23	  let isHookEnabled;
24	  try {
25	    ({ isHookEnabled } = require('./lib/ck-config-utils.cjs'));
26	  } catch {
27	    isHookEnabled = () => true;
28	  }
29	
30	  if (!isHookEnabled('knowledge-auto-refresh')) {
31	    process.exit(0);
32	  }
33	
34	  const STATE_FILE = path.join(__dirname, '..', 'knowledge-state.yaml');
35	  const REFRESH_LOCK = path.join(__dirname, '.logs', 'kb-refresh.lock');
36	  const REFRESH_LOG = path.join(__dirname, '.logs', 'kb-refresh.log');
37	  const PYTHON_PATH = path.join(__dirname, '..', 'skills', '.venv', 'Scripts', 'python.exe');
38	  const KB_LOADER = path.join(__dirname, '..', 'skills', 'business', 'feedback_loop', 'intelligent-kb-loader.py');
39	
40	  // Config
41	  const STALENESS_THRESHOLD_DAYS = 30;
42	  const STALE_RATIO_TRIGGER = 0.3;  // Trigger refresh if >30% stale
43	  const MAX_REFRESH_BATCH = 5;
44	
45	  function ensureLogDir() {
46	    const logDir = path.join(__dirname, '.logs');
47	    if (!fs.existsSync(logDir)) fs.mkdirSync(logDir, { recursive: true });
48	  }
49	
50	  function isRefreshRunning() {
51	    if (!fs.existsSync(REFRESH_LOCK)) return false;
52	    try {
53	      const lockData = JSON.parse(fs.readFileSync(REFRESH_LOCK, 'utf8'));
54	      const lockAge = Date.now() - new Date(lockData.started).getTime();
55	      // Lock expires after 10 minutes
56	      return lockAge < 600000;
57	    } catch {
58	      return false;
59	    }
60	  }
61	
62	  function createRefreshLock(personas) {
63	    ensureLogDir();
64	    fs.writeFileSync(REFRESH_LOCK, JSON.stringify({
65	      started: new Date().toISOString(),
66	      personas,
67	      pid: process.pid
68	    }));
69	  }
70	
71	  function clearRefreshLock() {
72	    if (fs.existsSync(REFRESH_LOCK)) {
73	      fs.unlinkSync(REFRESH_LOCK);
74	    }
75	  }
76	
77	  function parseKnowledgeState() {
78	    if (!fs.existsSync(STATE_FILE)) return { personas: {}, threshold: STALENESS_THRESHOLD_DAYS };
79	
80	    const content = fs.readFileSync(STATE_FILE, 'utf-8');
81	    const lines = content.split('\n');
82	
83	    let threshold = STALENESS_THRESHOLD_DAYS;
84	    let inPersonas = false;
85	    let currentPersona = null;
86	    const personas = {};
87	
88	    for (const line of lines) {
89	      const trimmed = line.trim();
90	
91	      if (trimmed.startsWith('staleness_threshold_days:')) {
92	        threshold = parseInt(trimmed.split(':')[1].trim(), 10) || STALENESS_THRESHOLD_DAYS;
93	      } else if (trimmed === 'personas:') {
94	        inPersonas = true;
95	      } else if (inPersonas && line.startsWith('  ') && !line.startsWith('    ') && trimmed.endsWith(':')) {
96	        currentPersona = trimmed.slice(0, -1);
97	        personas[currentPersona] = { last_sync: null, freshness_score: 0 };
98	      } else if (currentPersona && line.startsWith('    ')) {
99	        if (trimmed.startsWith('last_sync:')) {
100	          const val = trimmed.split(':').slice(1).join(':').trim();
101	          personas[currentPersona].last_sync = val === 'null' ? null : val;
102	        } else if (trimmed.startsWith('freshness_score:')) {
103	          personas[currentPersona].freshness_score = parseFloat(trimmed.split(':')[1].trim()) || 0;
104	        }
105	      }
106	    }
107	
108	    return { personas, threshold };
109	  }
110	
111	  function getStalePersonas(personas, threshold) {
112	    const now = Date.now();
113	    const msPerDay = 86400000;
114	    const stale = [];
115	
116	    for (const [name, data] of Object.entries(personas)) {
117	      let daysSince = Infinity;
118	
119	      if (data.last_sync) {
120	        try {
121	          const syncDate = new Date(data.last_sync).getTime();
122	          daysSince = (now - syncDate) / msPerDay;
123	        } catch {
124	          daysSince = Infinity;
125	        }
126	      }
127	
128	      if (daysSince > threshold) {
129	        stale.push({
130	          name,
131	          days_stale: Math.floor(daysSince),
132	          freshness_score: data.freshness_score || 0
133	        });
134	      }
135	    }
136	
137	    // Sort by staleness (most stale first)
138	    stale.sort((a, b) => b.days_stale - a.days_stale);
139	
140	    return stale;
141	  }
142	
143	  function spawnBackgroundRefresh(personas) {
144	    ensureLogDir();
145	
146	    // Log refresh start
147	    fs.appendFileSync(REFRESH_LOG,
148	      `[${new Date().toISOString()}] Starting refresh for: ${personas.join(', ')}\n`
149	    );
150	
151	    // Create lock
152	    createRefreshLock(personas);
153	
154	    // Spawn background process for each persona
155	    // Using intelligent-kb-loader to trigger cache rebuild
156	    try {
157	      const child = spawn(PYTHON_PATH, [KB_LOADER, '--list-all', '--json'], {
158	        detached: true,
159	        stdio: ['ignore', 'pipe', 'pipe']
160	      });
161	
162	      child.stdout.on('data', (data) => {
163	        fs.appendFileSync(REFRESH_LOG, `[stdout] ${data.toString()}\n`);
164	      });
165	
166	      child.stderr.on('data', (data) => {
167	        fs.appendFileSync(REFRESH_LOG, `[stderr] ${data.toString()}\n`);
168	      });
169	
170	      child.on('close', (code) => {
171	        fs.appendFileSync(REFRESH_LOG,
172	          `[${new Date().toISOString()}] Refresh completed with code ${code}\n`
173	        );
174	        clearRefreshLock();
175	      });
176	
177	      child.unref();
